From 8181539517a43d2cbf0f04d5070318f99866fd07 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:45:56 +0100
Subject: [PATCH] applets/devicenotifier: don't treat system loop devices as
 removable

Snap and fstab loop devices are not mounted yet when they appear, so
they counted as removable, opened the popup by themselves and stayed
listed. Only unused loop devices set up by the user count as removable.

BUG: 521908
---
 applets/devicenotifier/storageinfo.cpp | 10 ++++++++--
 1 file changed, 8 insertions(+), 2 deletions(-)

diff --git a/applets/devicenotifier/storageinfo.cpp b/applets/devicenotifier/storageinfo.cpp
index 39851602b1..468289ed37 100644
--- a/applets/devicenotifier/storageinfo.cpp
+++ b/applets/devicenotifier/storageinfo.cpp
@@ -11,11 +11,14 @@
 #include <Solid/Block>
 #include <Solid/Camera>
 #include <Solid/DeviceNotifier>
+#include <Solid/GenericInterface>
 #include <Solid/OpticalDisc>
 #include <Solid/PortableMediaPlayer>
 #include <Solid/StorageAccess>
 #include <Solid/StorageDrive>

+#include <unistd.h>
+
 const QList<Solid::DeviceInterface::Type> StorageInfo::m_types({
     Solid::DeviceInterface::PortableMediaPlayer,
     Solid::DeviceInterface::Camera,
@@ -129,12 +132,15 @@ StorageInfo::StorageInfo(const QString &udi, QObject *parent)
         if (m_isRemovable) {
             m_hasRemovableParent = true;
         }
-        // Allow mount/unmount only for unused loop devices.
+        // Allow mount/unmount only for unused loop devices that the user set up.
         // Do not unmount a mounted loop device, as it may be in use or system-related.
+        // Loop devices set up by root (Snap packages, fstab entries) are briefly unused before the system mounts them.
         if (device.is<Solid::Block>() && device.is<Solid::StorageAccess>()) {
             auto block = device.as<Solid::Block>();
             auto access = device.as<Solid::StorageAccess>();
-            if (access && !access->isAccessible() && block && block->device().contains(QStringLiteral("/loop"))) {
+            auto generic = device.as<Solid::GenericInterface>();
+            if (access && !access->isAccessible() && block && block->device().contains(QStringLiteral("/loop")) && generic
+                && generic->property(QStringLiteral("SetupByUID")).toUInt() == getuid()) {
                 m_isRemovable = true;
             }
         }
-- 
